function generateDummyNotes(bpm, durationSec, density) {
    const arr = [];
    const totalBeats = (bpm / 60) * durationSec;
    for (let i = 4; i < totalBeats; i += (4 / density)) {
        if (Math.random() > 0.8) continue;
        const type = Math.random() > 0.9 ? 2 : (Math.random() > 0.5 ? 1 : 0);
        let row = 1 + Math.floor(Math.random() * 3);
        let col = 1 + Math.floor(Math.random() * 3);
        arr.push({ beat: i, col: col, row: row, type: type });
    }
    return arr;
}